CREATE TABLE benchmark_full_20260910.typed_building (event_id Nullable(Int64),occurred_at DateTime64(6, 'UTC'),environment String,event_type String,user_id Nullable(String),client_id Nullable(String),session_id Nullable(String),tab_id Nullable(String),path Nullable(String),feed_item_id Nullable(String),expansion_level Nullable(Decimal(38,6)),user_agent Nullable(String),ab_variant Nullable(String)) ENGINE=MergeTree PARTITION BY toYYYYMM(occurred_at) ORDER BY (environment,occurred_at,event_type);
